COASTERS = [("Family steel coaster", 15, 60), ("Hypercoaster", 65, 120), ("Gigacoaster", 95, 150)]
print("Steel coaster classifier")
for name, height, speed in COASTERS:
    if height >= 90:
        cls = "gigacoaster"
    elif height >= 60:
        cls = "hypercoaster"
    else:
        cls = "family / standard steel coaster"
    print("%s: %d m, %d km/h -> %s" % (name, height, speed, cls))
print("Steel track allows inversions and precise shapes that wood cannot.")
